<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { router,openLegal } from '../router.js'
import { state,t,bridge,run,saveLocale,finishSignOut,notify } from '../state.js'
import { personal,loadPersonal,personalAction } from '../personal-state.js'
import { content } from '../content-state.js'
import { person,socialAction } from '../social-state.js'
import { newId } from '../domain/id.js'
import '../delete-account-prompt.css'
import ContentShell from '../components/ContentShell.vue'
import AppModal from '../components/AppModal.vue'
import ActionButton from '../components/ActionButton.vue'
import AppIcon from '../components/AppIcon.vue'
const route=useRoute(),mode=computed(()=>route.name),status=ref('loading'),unblock=ref(null),deleting=ref(false),deletePrompt=ref(false),confirmEmail=ref(''),deleteCommit=ref(newId()),commit=ref(newId()),selectedTheme=ref(state.theme),selectedLocale=ref(state.locale),previewNotice=ref(false)
const title=computed(()=>t('p5.'+({settings:'settings',settingsTheme:'theme',settingsLanguage:'language',blocked:'blocklist',deleteAccount:'deleteAccount'}[mode.value]||'settings')))
const lifetime=new AbortController();let alive=true
async function load(){await loadPersonal();if(!alive)return;try{const r=await bridge.call('notifications','status',{}, {signal:lifetime.signal});if(alive)status.value=r.status}catch(e){if(alive&&e.code!=='CANCELLED')status.value='unsupported'}}
onMounted(load)
watch(mode,()=>{deletePrompt.value=false;deleting.value=false;previewNotice.value=false;commit.value=newId();if(mode.value==='settingsTheme')selectedTheme.value=state.theme;if(mode.value==='settingsLanguage')selectedLocale.value=state.locale;load()})
async function notifications(){if(status.value==='unsupported'){notify('p5.notification_unsupported');return}await run('settings-notifications',async signal=>{if(['denied','authorized','provisional','ephemeral'].includes(status.value)){await bridge.call('system','openSettings',{}, {signal});return}const r=await bridge.call('notifications','request',{}, {signal,timeout:120000});status.value=r.status})}
function foreground(){if(!document.hidden)bridge.call('notifications','status',{}, {signal:lifetime.signal}).then(r=>{if(alive)status.value=r.status}).catch(()=>{})}
document.addEventListener('visibilitychange',foreground)
import { onBeforeUnmount } from 'vue'
onBeforeUnmount(()=>{alive=false;lifetime.abort();document.removeEventListener('visibilitychange',foreground)})
async function saveTheme(){if(await personalAction('savePreferences',{theme:selectedTheme.value,commitId:commit.value})){state.theme=selectedTheme.value;await router.push('/settings')}}
async function saveLanguage(){if(await saveLocale(selectedLocale.value)!==false){notify('languageSaved');await router.push('/settings')}}
async function release(){if(await socialAction('block',{peerId:unblock.value.id,blocked:false})){unblock.value=null;await loadPersonal()}}
async function removeAccount(){await run('delete-account',async(signal,done)=>{const r=await bridge.call('personal','deleteAccount',{confirmed:true,confirmEmail:confirmEmail.value,commitId:deleteCommit.value},{signal});finishSignOut();notify(r.cleanupPending?'p5.cleanupPending':'p5.accountDeleted');done();await router.replace('/welcome')},{critical:true})}
function closeDeletePrompt(event){if(event?.detail>1)return;deletePrompt.value=false}
async function reviewDeletion(event){if(event?.detail>1||!deletePrompt.value)return;deletePrompt.value=false;await router.push('/settings/delete-account')}
function back(){router.push(mode.value==='settings'?'/mine':'/settings')}
const themeColors={pink:'rgba(255,0,153,1)',purple:'rgba(119,0,255,1)',orange:'rgba(255,143,31,1)',cyan:'rgba(0,255,255,1)'}
</script>
<template><ContentShell back class="p5-shell settings-shell" :data-preview="mode==='settingsTheme'?selectedTheme:undefined" :title="title" :ready="personal.loaded" :show-error="personal.loaded" @back="back"><div v-if="!personal.loaded" class="content-state"><p v-if="state.ui.error" class="error-banner" role="alert" :data-error-code="state.ui.error">{{ t('p5.loadFailed') }}</p><p v-else>{{ t('working') }}</p><ActionButton v-if="!state.ui.busy" @click="load">{{ t('retry') }}</ActionButton></div><template v-else-if="mode==='settings'"><section class="settings-section"><h2>{{ t('p5.appearance') }}</h2><button class="settings-row" @click="router.push('/settings/theme')"><img src="/images/p5/settings-theme.png" alt=""/><span>{{ t('p5.theme') }}</span><AppIcon name="arrow" :size="14"/></button><button class="settings-row" @click="router.push('/settings/language')"><AppIcon name="globe"/><span>{{ t('p5.language') }}</span><small>{{ state.locale==='fr'?'Français':'English' }}</small><AppIcon name="arrow" :size="14"/></button></section><section class="settings-section"><h2>{{ t('p5.notifications') }}</h2><button class="settings-row" :disabled="status==='loading'||!!state.ui.busy" @click="notifications"><img src="/images/p5/settings-notifications.png" alt=""/><span>{{ t('p5.pushMessages') }}</span><span class="notification-switch" :class="{on:['authorized','provisional','ephemeral'].includes(status)}"/><span class="sr-only">{{ t('p5.notification_'+status) }}</span></button><p class="field-hint">{{ t('p5.notification_'+status) }} </p></section><section class="settings-section"><h2>{{ t('p5.accountPrivacy') }}</h2><button class="settings-row" @click="router.push('/settings/blocked')"><img src="/images/p5/settings-blocklist.png" alt=""/><span>{{ t('p5.blocklist') }}</span><AppIcon name="arrow" :size="14"/></button><button class="settings-row" @click="deletePrompt=true"><img src="/images/p5/settings-delete.png" alt=""/><span>{{ t('p5.deleteAccount') }}</span><AppIcon name="arrow" :size="14"/></button></section><section class="settings-section"><h2>{{ t('p5.termsSection') }}</h2><button v-for="[key,icon,label] in [['terms','terms','terms'],['privacy','privacy','privacy'],['guidelines','agreement','community']]" :key="key" class="settings-row" @click="openLegal(key)"><img :src="'/images/p5/settings-'+icon+'.png'" alt=""/><span>{{ t(label) }}</span><AppIcon name="arrow" :size="14"/></button></section><button class="settings-row settings-logout" @click="state.ui.modal='logout'"><img src="/images/p5/settings-logout.png" alt=""/><span>{{ t('logout') }}</span><AppIcon name="arrow" :size="14"/></button></template><template v-else-if="mode==='settingsTheme'"><h2 class="p5-section-label">{{ t('p5.pickTheme') }}</h2><p class="field-hint">{{ t('p5.pickThemeHint') }}</p><div class="theme-swatches"><button v-for="id in ['pink','purple','orange','cyan']" :key="id" :aria-label="t('p5.theme_'+id)" :aria-pressed="selectedTheme===id" :disabled="!!state.ui.busy" :style="{backgroundColor:themeColors[id]}" @click="selectedTheme=id;previewNotice=false"><AppIcon v-if="selectedTheme===id" name="check"/></button></div><section class="theme-preview" :data-preview="selectedTheme"><div class="theme-preview-label"><span :style="{background:themeColors[selectedTheme]}"/><div><h2>{{ t('p5.preview') }}</h2><p>{{ t('p5.theme_'+selectedTheme) }}</p></div></div><div class="theme-preview-buttons"><ActionButton class="purple-gradient" @click="previewNotice=true">{{ t('p5.primaryButton') }}</ActionButton><ActionButton secondary @click="previewNotice=true">{{ t('p5.secondaryButton') }}</ActionButton></div><p v-if="previewNotice" role="status">{{ t('p5.previewHint') }}</p></section></template><template v-else-if="mode==='settingsLanguage'"><p class="field-hint">{{ t('p5.languageHint') }}</p><button v-for="[id,endonym,helper] in [['en','English','Anglais'],['fr','Français','French']]" :key="id" class="settings-row language-selection" :aria-pressed="selectedLocale===id" :disabled="!!state.ui.busy" @click="selectedLocale=id"><span><strong>{{ endonym }}</strong><small>{{ helper }}</small></span><AppIcon v-if="selectedLocale===id" name="check"/></button></template><template v-else-if="mode==='blocked'"><p class="field-hint">{{ t('p5.blocklistHint') }}</p><p v-if="!content.blockedAuthors.length" class="social-empty">{{ t('p5.noBlocked') }}</p><div v-for="x in content.blockedAuthors" :key="x.id" class="blocked-row"><img :src="person(x.id)?.photos?.[0]?.url||'/images/default-avatar.svg'" alt=""/><strong>{{ x.name }}</strong><button class="text-link" :disabled="!!state.ui.busy" @click="unblock=x">{{ t('s.unblock') }}</button></div></template><template v-else-if="mode==='deleteAccount'"><section class="account-delete-explanation"><h2>{{ t('p5.deleteAccount') }}</h2><p>{{ t('p5.deleteAccountHint') }}</p><strong>{{ state.user.email }}</strong><p>{{ t('p5.deleteScope') }}</p><p v-if="state.user.isTest" class="recovery-card">{{ t('p5.testProtected') }}</p><label class="p5-field"><span>{{ t('p5.confirmEmail') }}</span><input v-model="confirmEmail" type="email" autocomplete="off" autocapitalize="none" spellcheck="false" :disabled="state.user.isTest||!!state.ui.busy"/></label><ActionButton :disabled="state.user.isTest||confirmEmail.trim().toLowerCase()!==state.user.email||!!state.ui.busy" @click="state.ui.error=null;deleting=true">{{ t('p5.reviewDeletion') }}</ActionButton></section></template><template v-if="['settingsTheme','settingsLanguage'].includes(mode)" #footer><ActionButton class="purple-gradient" :disabled="!!state.ui.busy" :busy="state.ui.busy==='personal-savePreferences'||state.ui.busy==='locale'" @click="mode==='settingsTheme'?saveTheme():saveLanguage()">{{ t('save') }}</ActionButton></template></ContentShell><AppModal v-if="deletePrompt" centered variant="delete-account-prompt" :dismiss-on-backdrop="false" :title="t('p5.deleteAccount')" @close="closeDeletePrompt"><p>{{ t('p5.deleteAccountPrompt') }}</p><template #footer><ActionButton @click="reviewDeletion">{{ t('p5.understandDelete') }}</ActionButton><ActionButton secondary @click="closeDeletePrompt">{{ t('cancel') }}</ActionButton></template></AppModal><AppModal v-if="unblock" centered variant="personal-confirm" :title="t('s.unblock')" :closable="!state.ui.busy" @close="unblock=null"><p>{{ t('p5.unblockHint',{name:unblock.name}) }}</p><p v-if="state.ui.error" class="error-banner" :data-error-code="state.ui.error">{{ t('errors.'+state.ui.error) }}</p><template #footer><ActionButton secondary :disabled="!!state.ui.busy" @click="unblock=null">{{ t('cancel') }}</ActionButton><ActionButton :disabled="!!state.ui.busy" :busy="state.ui.busy==='social-block'" @click="release">{{ t('s.unblock') }}</ActionButton></template></AppModal><AppModal v-if="deleting" centered variant="account-confirm" :title="t('p5.deleteAccount')" :closable="!state.ui.busy" @close="deleting=false"><p>{{ t('p5.deleteAccountHint') }}</p><strong>{{ state.user?.email }}</strong><p v-if="state.ui.error" class="error-banner" role="alert" :data-error-code="state.ui.error">{{ t('errors.'+state.ui.error) }}</p><template #footer><ActionButton :disabled="!!state.ui.busy" :busy="state.ui.busy==='delete-account'" @click="removeAccount">{{ t('p5.understandDelete') }}</ActionButton><ActionButton secondary :disabled="!!state.ui.busy" @click="deleting=false">{{ t('cancel') }}</ActionButton></template></AppModal></template>
